from fastapi import FastAPI, HTTPException, status
from pydantic import BaseModel, Field

app = FastAPI()
NOTAS = []

class NotaCreate(BaseModel):
    texto: str = Field(..., min_length=1, max_length=500)
    tag: str = Field(..., min_length=1, max_length=50)

@app.get('/notas/{nota_id}')
def get_nota(nota_id: int):
    """GET exitoso → 200 OK (default)"""
    for nota in NOTAS:
        if nota['id'] == nota_id:
            return nota
    raise HTTPException(status_code=404, detail='Nota no encontrada')

@app.post('/notas', status_code=status.HTTP_201_CREATED)
def crear_nota(nota_in: NotaCreate):
    """POST exitoso → 201 Created"""
    # Validar unicidad
    if any(n['texto'] == nota_in.texto for n in NOTAS):
        raise HTTPException(
            status_code=status.HTTP_409_CONFLICT,
            detail=f'Ya existe una nota con el texto: {nota_in.texto}'
        )
    nueva = {'id': len(NOTAS) + 1, **nota_in.dict()}
    NOTAS.append(nueva)
    return nueva

@app.put('/notas/{nota_id}')
def actualizar_nota(nota_id: int, nota_in: NotaCreate):
    """PUT exitoso → 200 OK (default)"""
    for nota in NOTAS:
        if nota['id'] == nota_id:
            nota.update(nota_in.dict())
            return nota
    raise HTTPException(status_code=404, detail='Nota no encontrada')

@app.delete('/notas/{nota_id}', status_code=status.HTTP_204_NO_CONTENT)
def eliminar_nota(nota_id: int):
    """DELETE exitoso → 204 No Content (sin body)"""
    for i, nota in enumerate(NOTAS):
        if nota['id'] == nota_id:
            del NOTAS[i]
            return  # Sin body, solo el código 204
    raise HTTPException(status_code=404, detail='Nota no encontrada')

# ===== TABLA DE CÓDIGOS HTTP ESENCIALES =====
# 2xx ÉXITO
# 200 OK                    → Lectura/actualización exitosa
# 201 Created               → Recurso creado (POST exitoso)
# 204 No Content            → Eliminación exitosa, sin body
#
# 4xx ERROR DEL CLIENTE
# 400 Bad Request           → Error genérico del cliente (datos inválidos)
# 401 Unauthorized          → Autenticación requerida/fallida
# 403 Forbidden             → Autenticado pero sin permisos
# 404 Not Found             → Recurso no existe
# 409 Conflict              → Conflicto de estado (duplicado, versión)
# 422 Unprocessable Entity  → Validación de Pydantic falló
#
# 5xx ERROR DEL SERVIDOR
# 500 Internal Server Error → Bug en tu código (excepción no manejada)
# 503 Service Unavailable   → Servicio temporalmente caído

