from fastapi import FastAPI, Depends, HTTPException, status
from fastapi.security import HTTPBearer, HTTPAuthorizationCredentials
from pydantic import BaseModel
from typing import Generator

app = FastAPI()
security = HTTPBearer()

# ===== DEPENDENCIAS COMPONIBLES =====

# 1. Dependencia de base de datos (patrón común)
class FakeDB:
    """Simulación de conexión a DB (en Fase 2.2 será SQLAlchemy real)."""
    def __init__(self):
        self.connected = True

    def query(self, sql):
        return []

    def close(self):
        self.connected = False

def get_db() -> Generator[FakeDB, None, None]:
    """Dependencia que crea la conexión, la yield, y la cierra después."""
    db = FakeDB()
    try:
        yield db  # El endpoint usa 'db'
    finally:
        db.close()  # Se cierra automáticamente después del endpoint

# 2. Dependencia de autenticación
def get_current_user(
    credentials: HTTPAuthorizationCredentials = Depends(security)
) -> dict:
    """Verifica el token y retorna el usuario autenticado."""
    token = credentials.credentials
    # En producción: decodificar JWT, verificar firma, consultar DB
    if token == 'valid-token':
        return {'user_id': 1, 'username': 'ana', 'role': 'user'}
    raise HTTPException(
        status_code=status.HTTP_401_UNAUTHORIZED,
        detail='Token inválido o expirado',
        headers={'WWW-Authenticate': 'Bearer'},
    )

# 3. Dependencia que depende de otra (composición)
def get_admin_user(user: dict = Depends(get_current_user)) -> dict:
    """Verifica que el usuario autenticado sea admin."""
    if user.get('role') != 'admin':
        raise HTTPException(
            status_code=status.HTTP_403_FORBIDDEN,
            detail='Se requieren permisos de administrador',
        )
    return user

# 4. Dependencia de paginación (parámetros comunes)
def get_pagination(
    limit: int = 10,
    offset: int = 0,
) -> dict:
    """Extrae y valida parámetros de paginación."""
    return {'limit': min(limit, 100), 'offset': max(offset, 0)}

# ===== ENDPOINTS CON DEPENDENCIAS =====

class NotaCreate(BaseModel):
    texto: str
    tag: str

NOTAS = []

@app.get('/notas')
def list_notas(
    db: FakeDB = Depends(get_db),
    user: dict = Depends(get_current_user),
    pagination: dict = Depends(get_pagination),
):
    """Endpoint con múltiples dependencias inyectadas."""
    # db ya está conectada (get_db la creó)
    # user ya está autenticado (get_current_user lo verificó)
    # pagination ya está validado (get_pagination lo procesó)

    return {
        'notas': NOTAS[pagination['offset']:pagination['offset'] + pagination['limit']],
        'user': user['username'],
        'pagination': pagination,
    }

@app.post('/notas', status_code=201)
def crear_nota(
    nota_in: NotaCreate,
    db: FakeDB = Depends(get_db),
    user: dict = Depends(get_current_user),
):
    """Solo usuarios autenticados pueden crear notas."""
    nueva = {'id': len(NOTAS) + 1, **nota_in.dict(), 'user_id': user['user_id']}
    NOTAS.append(nueva)
    return nueva

@app.delete('/admin/notas/{nota_id}', status_code=204)
def admin_eliminar_nota(
    nota_id: int,
    admin: dict = Depends(get_admin_user),  # Solo admins
):
    """Endpoint protegido: solo admins pueden eliminar."""
    for i, nota in enumerate(NOTAS):
        if nota['id'] == nota_id:
            del NOTAS[i]
            return
    raise HTTPException(status_code=404, detail='Nota no encontrada')

# ===== FLUJO DE EJECUCIÓN =====
# 1. Petición llega a FastAPI
# 2. FastAPI ejecuta las dependencias en orden (get_db, get_current_user, get_pagination)
# 3. Si alguna dependencia lanza HTTPException, FastAPI retorna ese error
# 4. Si todas pasan, FastAPI llama el endpoint con los valores inyectados
# 5. Después del endpoint, FastAPI ejecuta el 'finally' de las dependencias con yield
#    (en este caso, db.close())

